1	package server
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/json"
9		"io"
10		"maps"
11		"mime"
12		"net/http"
13		"net/url"
14		"sort"
15		"strconv"
16		"strings"
17		"time"
18	)
19	
20	const (
21		logsPath = "/api/v1/logs"
22	
23		maxLogBatch        = 500
24		maxLogIDsPerTenant = 10000
25		maxLogIDLen        = 128
26		defaultLogLimit    = 100
27		maxLogLimit        = 200
28	)
29	
30	var logLevels = map[string]bool{
31		"debug": true,
32		"info":  true,
33		"warn":  true,
34		"error": true,
35	}
36	
37	// logEntry is one committed log record. Entries are immutable once stored;
38	// only eviction removes them.
39	type logEntry struct {
40		id        string
41		timestamp time.Time
42		level     string
43		message   string
44		labels    map[string]string
45		traceID   string // "" when absent
46		seq       int64  // commit sequence, assigned at insert
47	}
48	
49	// sameContent reports whether two entries with the same id carry the same
50	// timestamp instant and the same remaining content, making the later one a
51	// replay rather than a conflict.
52	func (e *logEntry) sameContent(other *logEntry) bool {
53		return e.id == other.id &&
54			e.timestamp.Equal(other.timestamp) &&
55			e.level == other.level &&
56			e.message == other.message &&
57			e.traceID == other.traceID &&
58			maps.Equal(e.labels, other.labels)
59	}
60	
61	// checkAndApplyLogs validates the batch against committed state (and against
62	// itself) and then commits it in array order. A false result signals a
63	// content conflict on a repeated id; in that case no state is mutated.
64	// Replays — repeats of an id with identical content — are counted but do not
65	// mutate state or refresh eviction order.
66	func (s *metricStore) checkAndApplyLogs(batch []*logEntry) (accepted, replayed int, ok bool) {
67		s.mu.Lock()
68		defer s.mu.Unlock()
69	
70		// First pass: conflict detection against committed entries and earlier
71		// entries in the same batch.
72		seen := make(map[string]*logEntry, len(batch))
73		for _, e := range batch {
74			if prev, dup := seen[e.id]; dup {
75				if !prev.sameContent(e) {
76					return 0, 0, false
77				}
78				continue
79			}
80			if existing, committed := s.logs[e.id]; committed && !existing.sameContent(e) {
81				return 0, 0, false
82			}
83			seen[e.id] = e
84		}
85	
86		// Second pass: commit in array order, then evict the oldest ids until
87		// the tenant is back within the retention bound.
88		for _, e := range batch {
89			if _, exists := s.logs[e.id]; exists {
90				replayed++
91				continue
92			}
93			s.logSeq++
94			e.seq = s.logSeq
95			s.logs[e.id] = e
96			s.logOrder = append(s.logOrder, e.id)
97			accepted++
98		}
99		if len(s.logOrder) > maxLogIDsPerTenant {
100			excess := len(s.logOrder) - maxLogIDsPerTenant
101			for _, id := range s.logOrder[:excess] {
102				delete(s.logs, id)
103			}
104			s.logOrder = append([]string(nil), s.logOrder[excess:]...)
105		}
106		return accepted, replayed, true
107	}
108	
109	// logFilter is the immutable condition set of a log query. A nil entry in
110	// hasStart/hasEnd marks an open bound.
111	type logFilter struct {
112		start    time.Time
113		hasStart bool
114		end      time.Time
115		hasEnd   bool
116		level    string
117		traceID  string
118		q        string
119		labels   map[string]string
120	}
121	
122	func (f *logFilter) matches(e *logEntry) bool {
123		if f.hasStart && e.timestamp.Before(f.start) {
124			return false
125		}
126		if f.hasEnd && !e.timestamp.Before(f.end) {
127			return false
128		}
129		if f.level != "" && e.level != f.level {
130			return false
131		}
132		if f.traceID != "" && e.traceID != f.traceID {
133			return false
134		}
135		if f.q != "" && !strings.Contains(e.message, f.q) {
136			return false
137		}
138		for k, v := range f.labels {
139			got, ok := e.labels[k]
140			if !ok || got != v {
141				return false
142			}
143		}
144		return true
145	}
146	
147	// queryLogs returns the page of entries matching the filter within the
148	// snapshot (entries with seq <= snapshotSeq), strictly after the position
149	// (afterTS, afterID) in result order, plus whether more entries remain.
150	// Result order is timestamp descending, id ascending within one instant.
151	func (s *metricStore) queryLogs(f *logFilter, snapshotSeq int64, afterTS time.Time, afterID string, hasAfter bool, limit int) ([]*logEntry, bool) {
152		s.mu.RLock()
153		defer s.mu.RUnlock()
154	
155		matched := make([]*logEntry, 0)
156		for _, e := range s.logs {
157			if e.seq > snapshotSeq {
158				continue // written after the snapshot anchor; never mixes in
159			}
160			if !f.matches(e) {
161				continue
162			}
163			if hasAfter && !comesAfter(e, afterTS, afterID) {
164				continue
165			}
166			matched = append(matched, e)
167		}
168		sort.Slice(matched, func(i, j int) bool {
169			a, b := matched[i], matched[j]
170			if !a.timestamp.Equal(b.timestamp) {
171				return a.timestamp.After(b.timestamp)
172			}
173			return a.id < b.id
174		})
175	
176		more := len(matched) > limit
177		if more {
178			matched = matched[:limit]
179		}
180		return matched, more
181	}
182	
183	// comesAfter reports whether e sorts strictly after the position (ts, id) in
184	// result order.
185	func comesAfter(e *logEntry, ts time.Time, id string) bool {
186		if e.timestamp.Equal(ts) {
187			return e.id > id
188		}
189		return e.timestamp.Before(ts)
190	}
191	
192	// ---- JSON wire shapes ------------------------------------------------------
193	
194	type logsEnvelope struct {
195		Entries *[]json.RawMessage `json:"entries"`
196	}
197	
198	type rawLogEntry struct {
199		ID        *string            `json:"id"`
200		Timestamp *string            `json:"timestamp"`
201		Level     *string            `json:"level"`
202		Message   *string            `json:"message"`
203		Labels    *map[string]string `json:"labels"`
204		TraceID   *string            `json:"trace_id"`
205	}
206	
207	type logEntryJSON struct {
208		ID        string            `json:"id"`
209		Timestamp string            `json:"timestamp"`
210		Level     string            `json:"level"`
211		Message   string            `json:"message"`
212		Labels    map[string]string `json:"labels"`
213		TraceID   string            `json:"trace_id,omitempty"`
214	}
215	
216	func (e *logEntry) wireJSON() logEntryJSON {
217		return logEntryJSON{
218			ID:        e.id,
219			Timestamp: e.timestamp.UTC().Format(time.RFC3339Nano),
220			Level:     e.level,
221			Message:   e.message,
222			Labels:    copyLabels(e.labels),
223			TraceID:   e.traceID,
224		}
225	}
226	
227	// decodeLogBatch performs every format and value check. It never returns a
228	// partially validated batch.
229	func decodeLogBatch(body []byte) ([]*logEntry, bool) {
230		var env logsEnvelope
231		if !strictDecode(body, &env) || env.Entries == nil || len(*env.Entries) == 0 || len(*env.Entries) > maxLogBatch {
232			return nil, false
233		}
234	
235		batch := make([]*logEntry, 0, len(*env.Entries))
236		for _, raw := range *env.Entries {
237			var re rawLogEntry
238			if !strictDecode(raw, &re) {
239				return nil, false
240			}
241			if re.ID == nil || re.Timestamp == nil || re.Level == nil || re.Message == nil || re.Labels == nil {
242				return nil, false
243			}
244			id := *re.ID
245			if !validLogID(id) {
246				return nil, false
247			}
248			ts, err := time.Parse(time.RFC3339Nano, *re.Timestamp)
249			if err != nil {
250				return nil, false
251			}
252			level := *re.Level
253			if !logLevels[level] {
254				return nil, false
255			}
256			labels := *re.Labels
257			if labels == nil {
258				return nil, false // explicit null labels
259			}
260			for k := range labels {
261				if !identPattern.MatchString(k) {
262					return nil, false
263				}
264			}
265			traceID := ""
266			if re.TraceID != nil {
267				traceID = *re.TraceID
268				if !validTraceID(traceID) {
269					return nil, false
270				}
271			}
272			batch = append(batch, &logEntry{
273				id:        id,
274				timestamp: ts,
275				level:     level,
276				message:   *re.Message,
277				labels:    copyLabels(labels),
278				traceID:   traceID,
279			})
280		}
281		return batch, true
282	}
283	
284	// validLogID reports whether id is 1-128 printable ASCII characters.
285	func validLogID(id string) bool {
286		if len(id) == 0 || len(id) > maxLogIDLen {
287			return false
288		}
289		for i := 0; i < len(id); i++ {
290			if id[i] < 0x20 || id[i] > 0x7e {
291				return false
292			}
293		}
294		return true
295	}
296	
297	func validTraceID(id string) bool {
298		if len(id) != 32 {
299			return false
300		}
301		for i := 0; i < len(id); i++ {
302			c := id[i]
303			if !('0' <= c && c <= '9' || 'a' <= c && c <= 'f') {
304				return false
305			}
306		}
307		return true
308	}
309	
310	// ---- cursor ----------------------------------------------------------------
311	
312	// logCursor pins the first request's conditions, page size and snapshot
313	// upper bound, plus the position the next page continues from.
314	type logCursor struct {
315		V        int               `json:"v"`
316		Tenant   string            `json:"tenant"`
317		Start    string            `json:"start,omitempty"`
318		End      string            `json:"end,omitempty"`
319		Level    string            `json:"level,omitempty"`
320		TraceID  string            `json:"trace_id,omitempty"`
321		Q        string            `json:"q,omitempty"`
322		Labels   map[string]string `json:"labels,omitempty"`
323		Limit    int               `json:"limit"`
324		Snapshot int64             `json:"snapshot"`
325		LastTS   string            `json:"last_ts"`
326		LastID   string            `json:"last_id"`
327	}
328	
329	// cursorKey signs cursors so tampered or foreign tokens are rejected as
330	// invalid_cursor. Log state is process-local, so a random per-process key is
331	// sufficient and cursors are not expected to survive restarts.
332	var cursorKey = func() []byte {
333		key := make([]byte, 32)
334		if _, err := rand.Read(key); err != nil {
335			panic(err)
336		}
337		return key
338	}()
339	
340	func encodeCursor(c *logCursor) string {
341		payload, _ := json.Marshal(c)
342		mac := hmac.New(sha256.New, cursorKey)
343		mac.Write(payload)
344		return base64.RawURLEncoding.EncodeToString(payload) + "." +
345			base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
346	}
347	
348	// decodeCursor parses and validates a cursor token. The boolean is false for
349	// any malformed, tampered or otherwise unusable token.
350	func decodeCursor(token string) (*logCursor, bool) {
351		payloadPart, macPart, ok := strings.Cut(token, ".")
352		if !ok {
353			return nil, false
354		}
355		payload, err := base64.RawURLEncoding.DecodeString(payloadPart)
356		if err != nil {
357			return nil, false
358		}
359		wantMAC, err := base64.RawURLEncoding.DecodeString(macPart)
360		if err != nil {
361			return nil, false
362		}
363		mac := hmac.New(sha256.New, cursorKey)
364		mac.Write(payload)
365		if !hmac.Equal(mac.Sum(nil), wantMAC) {
366			return nil, false
367		}
368		var c logCursor
369		if !strictDecode(payload, &c) {
370			return nil, false
371		}
372		if c.V != 1 || c.Tenant == "" || c.Limit < 1 || c.Limit > maxLogLimit || c.Snapshot < 0 {
373			return nil, false
374		}
375		if c.Level != "" && !logLevels[c.Level] {
376			return nil, false
377		}
378		if c.TraceID != "" && !validTraceID(c.TraceID) {
379			return nil, false
380		}
381		for k := range c.Labels {
382			if !identPattern.MatchString(k) {
383				return nil, false
384			}
385		}
386		if c.Start != "" {
387			if _, err := time.Parse(time.RFC3339Nano, c.Start); err != nil {
388				return nil, false
389			}
390		}
391		if c.End != "" {
392			if _, err := time.Parse(time.RFC3339Nano, c.End); err != nil {
393				return nil, false
394			}
395		}
396		if _, err := time.Parse(time.RFC3339Nano, c.LastTS); err != nil {
397			return nil, false
398		}
399		if !validLogID(c.LastID) {
400			return nil, false
401		}
402		return &c, true
403	}
404	
405	// ---- HTTP handlers ---------------------------------------------------------
406	
407	func registerLogHandlers(mux *http.ServeMux) {
408		mux.HandleFunc(logsPath, func(w http.ResponseWriter, r *http.Request) {
409			switch r.Method {
410			case http.MethodGet:
411				handleLogsGet(w, r)
412			case http.MethodPost:
413				handleLogsPost(w, r)
414			default:
415				w.Header().Set("Allow", "GET, POST")
416				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
417			}
418		})
419	}
420	
421	func handleLogsPost(w http.ResponseWriter, r *http.Request) {
422		store := tenantStore(r)
423		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
424		if err != nil || mediaType != "application/json" {
425			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
426			return
427		}
428	
429		body, err := io.ReadAll(r.Body)
430		if err != nil {
431			writeAPIError(w, "invalid_logs", http.StatusBadRequest)
432			return
433		}
434	
435		batch, ok := decodeLogBatch(body)
436		if !ok {
437			writeAPIError(w, "invalid_logs", http.StatusBadRequest)
438			return
439		}
440	
441		accepted, replayed, applied := store.checkAndApplyLogs(batch)
442		if !applied {
443			writeAPIError(w, "log_conflict", http.StatusConflict)
444			return
445		}
446	
447		writeJSON(w, http.StatusAccepted, map[string]int{"accepted": accepted, "replayed": replayed})
448	}
449	
450	func handleLogsGet(w http.ResponseWriter, r *http.Request) {
451		store := tenantStore(r)
452		values, err := url.ParseQuery(r.URL.RawQuery)
453		if err != nil {
454			writeAPIError(w, "invalid_log_query", http.StatusBadRequest)
455			return
456		}
457	
458		if cursors, present := values["cursor"]; present {
459			// A follow-up request carries exactly one cursor and nothing else.
460			if len(values) != 1 || len(cursors) != 1 {
461				writeAPIError(w, "invalid_log_query", http.StatusBadRequest)
462				return
463			}
464			cursor, ok := decodeCursor(cursors[0])
465			if !ok || cursor.Tenant != tenantName(r) {
466				writeAPIError(w, "invalid_cursor", http.StatusBadRequest)
467				return
468			}
469			serveLogPage(w, store, cursor)
470			return
471		}
472	
473		filter, limit, ok := parseLogQuery(values)
474		if !ok {
475			writeAPIError(w, "invalid_log_query", http.StatusBadRequest)
476			return
477		}
478	
479		store.mu.RLock()
480		snapshot := store.logSeq
481		store.mu.RUnlock()
482	
483		cursor := &logCursor{
484			V:        1,
485			Tenant:   tenantName(r),
486			Level:    filter.level,
487			TraceID:  filter.traceID,
488			Q:        filter.q,
489			Labels:   filter.labels,
490			Limit:    limit,
491			Snapshot: snapshot,
492		}
493		if filter.hasStart {
494			cursor.Start = filter.start.UTC().Format(time.RFC3339Nano)
495		}
496		if filter.hasEnd {
497			cursor.End = filter.end.UTC().Format(time.RFC3339Nano)
498		}
499		serveLogPage(w, store, cursor)
500	}
501	
502	// serveLogPage runs the paginated query described by cursor and writes the
503	// response, refreshing the cursor's position for the next page.
504	func serveLogPage(w http.ResponseWriter, store *metricStore, cursor *logCursor) {
505		filter := &logFilter{
506			level:   cursor.Level,
507			traceID: cursor.TraceID,
508			q:       cursor.Q,
509			labels:  cursor.Labels,
510		}
511		if cursor.Start != "" {
512			filter.start, _ = time.Parse(time.RFC3339Nano, cursor.Start)
513			filter.hasStart = true
514		}
515		if cursor.End != "" {
516			filter.end, _ = time.Parse(time.RFC3339Nano, cursor.End)
517			filter.hasEnd = true
518		}
519	
520		var afterTS time.Time
521		hasAfter := cursor.LastTS != ""
522		if hasAfter {
523			afterTS, _ = time.Parse(time.RFC3339Nano, cursor.LastTS)
524		}
525	
526		page, more := store.queryLogs(filter, cursor.Snapshot, afterTS, cursor.LastID, hasAfter, cursor.Limit)
527	
528		entries := make([]logEntryJSON, 0, len(page))
529		for _, e := range page {
530			entries = append(entries, e.wireJSON())
531		}
532	
533		var nextCursor *string
534		if more {
535			last := page[len(page)-1]
536			cursor.LastTS = last.timestamp.UTC().Format(time.RFC3339Nano)
537			cursor.LastID = last.id
538			token := encodeCursor(cursor)
539			nextCursor = &token
540		}
541	
542		writeJSON(w, http.StatusOK, map[string]any{"entries": entries, "next_cursor": nextCursor})
543	}
544	
545	// parseLogQuery validates the first-request query parameters and builds the
546	// filter. Only the documented parameter vocabulary is accepted.
547	func parseLogQuery(values url.Values) (*logFilter, int, bool) {
548		filter := &logFilter{labels: map[string]string{}}
549		limit := defaultLogLimit
550	
551		for key, vals := range values {
552			if len(vals) == 0 {
553				return nil, 0, false
554			}
555			// A repeated parameter is accepted only when every value agrees.
556			for _, v := range vals[1:] {
557				if v != vals[0] {
558					return nil, 0, false
559				}
560			}
561			value := vals[0]
562			switch {
563			case key == "start":
564				ts, err := time.Parse(time.RFC3339Nano, value)
565				if err != nil {
566					return nil, 0, false
567				}
568				filter.start, filter.hasStart = ts, true
569			case key == "end":
570				ts, err := time.Parse(time.RFC3339Nano, value)
571				if err != nil {
572					return nil, 0, false
573				}
574				filter.end, filter.hasEnd = ts, true
575			case key == "level":
576				if !logLevels[value] {
577					return nil, 0, false
578				}
579				filter.level = value
580			case key == "trace_id":
581				if !validTraceID(value) {
582					return nil, 0, false
583				}
584				filter.traceID = value
585			case key == "q":
586				filter.q = value
587			case key == "limit":
588				n, err := strconv.Atoi(value)
589				if err != nil || n < 1 || n > maxLogLimit {
590					return nil, 0, false
591				}
592				limit = n
593			case strings.HasPrefix(key, "label."):
594				labelKey := strings.TrimPrefix(key, "label.")
595				if !identPattern.MatchString(labelKey) {
596					return nil, 0, false
597				}
598				filter.labels[labelKey] = value
599			default:
600				return nil, 0, false
601			}
602		}
603		return filter, limit, true
604	}
