		"empty service":       `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "", "root", "2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `{}`) + `]}`,
		"empty name":          `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "", "2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `{}`) + `]}`,
		"service non-string":  `{"spans":[{` +
			`"trace_id":"` + validTraceID + `","span_id":"0000000000000001","parent_span_id":null,` +
			`"service":7,"name":"root","start_time":"2026-01-02T03:04:05Z",` +
			`"end_time":"2026-01-02T03:04:06Z","status":"ok","attributes":{}}]}`,
		"bad time format":  `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "root", "2026-01-02 03:04:05", "2026-01-02T03:04:06Z", "ok", `{}`) + `]}`,
		"naive timestamp":  `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "root", "2026-01-02T03:04:05", "2026-01-02T03:04:06", "ok", `{}`) + `]}`,
		"end before start": `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "root", "2026-01-02T03:04:06Z", "2026-01-02T03:04:05Z", "ok", `{}`) + `]}`,
		"bad status":       `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "root", "2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "failed", `{}`) + `]}`,
		"attributes null":  `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "root", "2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `null`) + `]}`,
		"attribute value null": `{"spans":[{` +
			`"trace_id":"` + validTraceID + `","span_id":"0000000000000001","parent_span_id":null,` +
			`"service":"web","name":"root","start_time":"2026-01-02T03:04:05Z",` +
			`"end_time":"2026-01-02T03:04:06Z","status":"ok","attributes":{"route":null}}]}`,
		"bad attribute key": `{"spans":[` + makeSpan(validTraceID, "0000000000000001", "", "web", "root", "2026-01-02T03:04:05Z", "2026-01-02T03:04:06Z", "ok", `{"bad-key":"v"}`) + `]}`,
	}
	for name, body := range cases {
		t.Run(name, func(t *testing.T) {
			rec := postSpans(t, h, body)
			if rec.Code != http.StatusBadRequest || errorCode(t, rec) != "invalid_spans" {
				t.Fatalf("status = %d code = %q, want 400 invalid_spans", rec.Code, errorCode(t, rec))
			}
		})
	}

	// No invalid batch may have created a span.
	rec := getTrace(t, h, tracesPrefix+validTraceID)
	if rec.Code != http.StatusNotFound {
		t.Fatalf("invalid batches changed state: trace status = %d, want 404", rec.Code)
	}
}

